function gTick(){const ns=gNodes;for(let i=0;i<ns.length;i++){const a=ns[i];if(a.pinned)continue;for(let j=i+1;j<ns.length;j++){const b=ns[j];let dx=b.x-a.x,dy=b.y-a.y;const d2=dx*dx+dy*dy+1,d=Math.sqrt(d2);const f=G_REPEL/d2,fx=f*dx/d,fy=f*dy/d;a.vx-=fx;a.vy-=fy;if(!b.pinned){b.vx+=fx;b.vy+=fy;}}}for(const e of GEDGES){const a=gNodeMap[e.s],b=gNodeMap[e.t];if(!a||!b)continue;const dx=b.x-a.x,dy=b.y-a.y,d=Math.sqrt(dx*dx+dy*dy)+0.001;const f=G_SPRING*(d-G_IDEAL),fx=f*dx/d,fy=f*dy/d;if(!a.pinned){a.vx+=fx;a.vy+=fy;}if(!b.pinned){b.vx-=fx;b.vy-=fy;}}for(const n of ns){if(n.pinned)continue;n.vx+=-n.x*G_GRAVITY;n.vy+=-n.y*G_GRAVITY;n.vx*=G_DAMPING;n.vy*=G_DAMPING;n.x+=n.vx;n.y+=n.vy;}}
function runGraphLayout(steps){gNodes.forEach(n=>{n.pinned=false;n.vx=0;n.vy=0;});for(let i=0;i<steps;i++)gTick();gRender();}
