function gRender(){const svgGe=document.getElementById('ge'),svgGn=document.getElementById('gn');svgGe.innerHTML='';svgGn.innerHTML='';function el(tag,attrs){const e=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,v);return e;}
for(const e of GEDGES){const a=gNodeMap[e.s],b=gNodeMap[e.t];if(!a||!b)continue;const st=GESTYLE[e.type]||GESTYLE.uses;const dx=b.x-a.x,dy=b.y-a.y,d=Math.sqrt(dx*dx+dy*dy)+0.001;const sr=a.r+2,er=b.r+(st.mk?9:2);const x1=a.x+dx/d*sr,y1=a.y+dy/d*sr,x2=b.x-dx/d*er,y2=b.y-dy/d*er;const line=el('line',{x1,y1,x2,y2,stroke:st.color,'stroke-width':st.w,opacity:e.type==='member'?'0.25':'0.65','data-gs':e.s,'data-gt':e.t});if(st.dash)line.setAttribute('stroke-dasharray',st.dash);if(st.mk)line.setAttribute('marker-end',`url(#${st.mk})`);svgGe.appendChild(line);}
for(const n of gNodes){const isCat=n.id.startsWith('cat-');const g=el('g',{transform:`translate(${n.x.toFixed(1)},${n.y.toFixed(1)})`,cursor:'pointer','data-g-node-id':n.id});const circle=el('circle',{r:n.r,fill:n.color+'22',stroke:n.color,'stroke-width':isCat?'2.5':'1.5'});g.appendChild(circle);const lines=n.label.split('\n');const lh=11,sy=-(lines.length-1)*lh/2;lines.forEach((lbl,i)=>{const t=el('text',{'text-anchor':'middle','dominant-baseline':'middle',y:sy+i*lh,'font-size':n.r>28?'10':'9','font-family':'Segoe UI,system-ui,sans-serif','font-weight':'700',fill:n.color,'pointer-events':'none'});t.textContent=lbl;g.appendChild(t);});g.addEventListener('mouseenter',()=>{circle.setAttribute('fill',n.color+'44');circle.setAttribute('stroke-width','2.5');});g.addEventListener('mouseleave',()=>{if(gDragNode!==n){circle.setAttribute('fill',n.color+'22');circle.setAttribute('stroke-width',isCat?'2.5':'1.5');}});g.addEventListener('mousedown',ev=>{ev.stopPropagation();gDragNode=n;n.pinned=true;const pt=gSvgPt(ev);gDragOff={x:pt.x-n.x,y:pt.y-n.y};});g.addEventListener('click',ev=>{ev.stopPropagation();if(n.nodeId&&NODE_DATA[n.nodeId])openDetail(n.nodeId);});svgGn.appendChild(g);}gApplyTx();if(activeCat)applyGraphFilter(activeCat);}
function gSvgPt(e){const r=document.getElementById('graph-svg').getBoundingClientRect();return{x:(e.clientX-r.left-gTx.x)/gTx.k,y:(e.clientY-r.top-gTx.y)/gTx.k};}
function gApplyTx(){document.getElementById('graph-root').setAttribute('transform',`translate(${gTx.x.toFixed(1)},${gTx.y.toFixed(1)}) scale(${gTx.k.toFixed(4)})`);}
function fitGraph(){if(!gNodes.length)return;const svg=document.getElementById('graph-svg');const{width:W,height:H}=svg.getBoundingClientRect();let mnx=1e9,mxx=-1e9,mny=1e9,mxy=-1e9;gNodes.forEach(n=>{mnx=Math.min(mnx,n.x-n.r);mxx=Math.max(mxx,n.x+n.r);mny=Math.min(mny,n.y-n.r);mxy=Math.max(mxy,n.y+n.r);});const pad=50,k=Math.min((W-pad*2)/(mxx-mnx),(H-pad*2)/(mxy-mny),1.8);gTx.k=k;gTx.x=W/2-(mnx+mxx)/2*k;gTx.y=H/2-(mny+mxy)/2*k;gApplyTx();}
function gSetupInteraction(){const svg=document.getElementById('graph-svg');svg.addEventListener('wheel',e=>{e.preventDefault();const r=svg.getBoundingClientRect(),mx=e.clientX-r.left,my=e.clientY-r.top;const f=e.deltaY<0?1.12:0.89;gTx.x=mx-(mx-gTx.x)*f;gTx.y=my-(my-gTx.y)*f;gTx.k=Math.max(0.12,Math.min(4,gTx.k*f));gApplyTx();},{passive:false});svg.addEventListener('mousedown',e=>{const tgt=e.target;if(tgt===svg||tgt.id==='graph-root'||tgt.id==='ge'||tgt.id==='gn'){gPanning=true;gPanStart={x:e.clientX-gTx.x,y:e.clientY-gTx.y};}});window.addEventListener('mousemove',e=>{if(gDragNode){const pt=gSvgPt(e);gDragNode.x=pt.x-gDragOff.x;gDragNode.y=pt.y-gDragOff.y;gRender();}else if(gPanning){gTx.x=e.clientX-gPanStart.x;gTx.y=e.clientY-gPanStart.y;gApplyTx();}});window.addEventListener('mouseup',()=>{gDragNode=null;gPanning=false;});}
function applyGraphFilter(catId){const cat=CATEGORIES.find(c=>c.id===catId);if(!cat)return;const matchSet=new Set(cat.nodes);document.querySelectorAll('#gn > g[data-g-node-id]').forEach(g=>{const nid=g.dataset.gNodeId,isCat=nid.startsWith('cat-');const nodeId=GNODES.find(n=>n.id===nid)?.nodeId;const vis=isCat||(nodeId&&matchSet.has(nodeId));g.style.opacity=vis?'1':'0.05';g.style.pointerEvents=vis?'auto':'none';});document.querySelectorAll('#ge > line[data-gs][data-gt]').forEach(line=>{const sN=GNODES.find(n=>n.id===line.dataset.gs),tN=GNODES.find(n=>n.id===line.dataset.gt);const sv=!sN||sN.id.startsWith('cat-')||(sN.nodeId&&matchSet.has(sN.nodeId));const tv=!tN||tN.id.startsWith('cat-')||(tN.nodeId&&matchSet.has(tN.nodeId));line.style.opacity=(sv&&tv)?'0.6':'0.04';});}
function clearGraphFilter(){document.querySelectorAll('#gn > g[data-g-node-id]').forEach(g=>{g.style.opacity='';g.style.pointerEvents='';});document.querySelectorAll('#ge > line').forEach(l=>l.style.opacity='');}
function toggleGraphView(){gGraphActive=!gGraphActive;const btn=document.getElementById('btn-graph'),gview=document.getElementById('graph-view'),canvas=document.getElementById('canvas');if(gGraphActive){btn.style.cssText='border-color:var(--teal);color:var(--teal);background:rgba(26,188,156,.1)';gview.classList.add('visible');canvas.style.display='none';if(!gGraphInited){gNodes=GNODES.map(n=>({...n}));gNodeMap={};gNodes.forEach(n=>gNodeMap[n.id]=n);const deg={};gNodes.forEach(n=>deg[n.id]=0);GEDGES.forEach(e=>{if(deg[e.s]!==undefined)deg[e.s]++;if(deg[e.t]!==undefined)deg[e.t]++;});gNodes.forEach(n=>{n.r=n.id.startsWith('cat-')?36:Math.max(18,Math.min(34,18+(deg[n.id]||0)*1.4));});runGraphLayout(300);gSetupInteraction();gGraphInited=true;}setTimeout(fitGraph,60);if(activeCat)applyGraphFilter(activeCat);}else{btn.style.cssText='';gview.classList.remove('visible');canvas.style.display='';}}

