const GEDGE_DESC={'nids->port-mirror':'NIDS receives\ntraffic via SPAN','nids->port-tap':'Hardware tap\nprovides full capture','sig-ids->zero-day':'Signature IDS\nbLind to zero-days','trend-ids->zero-day':'Detects via\nbehavior change','nids->aggregator':'Sends alerts\nto aggregator','hids->aggregator':'Sends host\nevents to aggregator','apt->zero-day':'APTs exploit\nunknown vulnerabilities','apt->honeypot':'Honeypots catch\nAPTs early','honeynet->honeypot':'Honeynet is\nmultiple honeypots','wpa2->psk':'PSK mode uses\nshared passphrase','wpa2->enterprise-mode':'Enterprise uses\n802.1X/RADIUS','enterprise-mode->ieee8021x':'Enterprise requires\nport-based auth','ieee8021x->radius-fed':'802.1X authenticates\nvia RADIUS','wep->iv-attack':'WEP broken by\nIV reuse attack','wpa->wpa2':'WPA/TKIP replaced\nby WPA2/AES','wpa2->wpa3':'WPA3 upgrades\nSAE + stronger','wpa3->sae':'SAE replaces\nPSK handshake','wpa3->enhanced-open':'OWE encrypts\nopen networks','psk->sae':'SAE makes PSK\nresistant to offline attack','peap->eap-tls':'EAP-TLS stronger:\nrequires client cert','eap-tls->ptk':'Session PTK\nderived after auth','rogue-ap->evil-twin':'Both AP attacks\nbut different locations','disassoc->evil-twin':'Deauth forces\nreconnect to evil twin','bluetooth->bluejacking':'Bluejacking sends\nunsolicited messages','bluetooth->bluesnarfing':'Bluesnarfing steals\ndata silently','bluetooth->bluebugging':'Bluebugging gives\nfull device control','war-drive->wireless-audit':'Audit = authorized\nwar driving','vpn-conc->remote-vpn':'Concentrator handles\nclient VPN tunnels','vpn-conc->site-vpn':'Concentrator handles\nsite-to-site tunnels','tunnel-mode->esp':'Tunnel mode uses\nESP for encryption','transport-mode->esp':'Transport mode uses\nESP for payload','ike->esp':'IKE negotiates\nESP security assoc','l2tp->tunnel-mode':'L2TP creates\nthe tunnel','nac->ieee8021x':'NAC uses 802.1X\nfor port control','nac->agent-nac':'Agent = software\non endpoint','nac->agentless-nac':'Agentless = network\nside scanning','ppp->pap':'PPP carries\ninsecure PAP','ppp->chap':'PPP carries\nCHAP challenge','site-survey->heat-map':'Survey produces\nRF heat map','wifi-analyzer->site-survey':'Analyzer supports\nsite surveys',};
function getEdgeDesc(e){return GEDGE_DESC[`${e.s}->${e.t}`]||null;}
const _origGRender=gRender;
gRender=function(){if(!illustratedMode){_origGRender();return;}const svgGe=document.getElementById('ge'),svgGn=document.getElementById('gn');svgGe.innerHTML='';svgGn.innerHTML='';function el(tag,attrs){const e=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,v);return e;}
for(const e of GEDGES){const a=gNodeMap[e.s],b=gNodeMap[e.t];if(!a||!b)continue;const st=GESTYLE[e.type]||GESTYLE.uses;const dx=b.x-a.x,dy=b.y-a.y,d=Math.sqrt(dx*dx+dy*dy)+0.001;const sr=38,er=38+(st.mk?9:2);const x1=a.x+dx/d*sr,y1=a.y+dy/d*sr,x2=b.x-dx/d*er,y2=b.y-dy/d*er;const line=el('line',{x1,y1,x2,y2,stroke:st.color,'stroke-width':st.w,opacity:e.type==='member'?'0.2':'0.7','data-gs':e.s,'data-gt':e.t});if(st.dash)line.setAttribute('stroke-dasharray',st.dash);if(st.mk)line.setAttribute('marker-end',`url(#${st.mk})`);svgGe.appendChild(line);const desc=getEdgeDesc(e);if(desc&&e.type!=='member'){const mx=(a.x+b.x)/2,my=(a.y+b.y)/2;const lines=desc.split('\n');const bw=78,bh=lines.length*10+6;svgGe.appendChild(el('rect',{x:mx-bw/2,y:my-bh/2,width:bw,height:bh,rx:'3',fill:'#07090f',stroke:st.color,'stroke-width':'0.5',opacity:'0.92'}));lines.forEach((ln,i)=>{const t=el('text',{x:mx,y:my-(lines.length-1)*5+i*10,'text-anchor':'middle','dominant-baseline':'middle','font-size':'7.5','font-family':'Segoe UI,system-ui,sans-serif','font-weight':'600',fill:st.color,'pointer-events':'none'});t.textContent=ln;svgGe.appendChild(t);});}}
const NW=72,NH=58;for(const n of gNodes){const isCat=n.id.startsWith('cat-');const g=el('g',{transform:`translate(${n.x.toFixed(1)},${n.y.toFixed(1)})`,cursor:'pointer','data-g-node-id':n.id});const rect=el('rect',{x:-NW/2,y:-NH/2,width:NW,height:NH,rx:'8',fill:n.color+'18',stroke:n.color,'stroke-width':isCat?'2.5':'1.5'});g.appendChild(rect);const icon=el('text',{y:'-7','text-anchor':'middle','dominant-baseline':'middle','font-size':isCat?'20':'16','pointer-events':'none'});icon.textContent=GICONS[n.id]||'●';g.appendChild(icon);const lbl=el('text',{y:'13','text-anchor':'middle','dominant-baseline':'middle','font-size':'7.5','font-family':'Segoe UI,system-ui,sans-serif','font-weight':'700',fill:n.color,'pointer-events':'none'});lbl.textContent=n.label.replace(/\n/g,' ');g.appendChild(lbl);g.addEventListener('mouseenter',()=>rect.setAttribute('fill',n.color+'35'));g.addEventListener('mouseleave',()=>{if(gDragNode!==n)rect.setAttribute('fill',n.color+'18');});g.addEventListener('mousedown',ev=>{ev.stopPropagation();gDragNode=n;n.pinned=true;const pt=gSvgPt(ev);gDragOff={x:pt.x-n.x,y:pt.y-n.y};});g.addEventListener('click',ev=>{ev.stopPropagation();if(n.nodeId&&NODE_DATA[n.nodeId])openDetail(n.nodeId);});svgGn.appendChild(g);}gApplyTx();if(activeCat)applyGraphFilter(activeCat);};
function toggleIllustrated(){if(!gGraphActive)toggleGraphView();illustratedMode=!illustratedMode;const btn=document.getElementById('btn-illustrated');btn.style.cssText=illustratedMode?'border-color:var(--purple);color:var(--purple);background:rgba(155,89,182,.12)':'';btn.textContent=illustratedMode?'🖼 Bubble View':'🖼 Illustrated';gRender();}

let studyMode=false;
